def followup_view(inputs, prior):
    packet=inputs.get('seventeenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('seventeenth period packet changed')
    if prior is None or prior['counts']['after']!=110 or packet['prior_digest']!=digest(prior):raise ValueError('seventeenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('seventeenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=33 or len(packet['sources'])!=33 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('seventeenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('seventeenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('seventeenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('seventeenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('seventeenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('seventeenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('seventeenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('seventeenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('seventeenth period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('seventeenth period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
